#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long m;
    long long n;
    cin >> m >> n;
    vector<long long> a(m);
    for (int i = 0; i < m; i++) cin >> a[i];

    long long miss = 1, patches = 0, i = 0;
    while (miss <= n) {
        if (i < m && a[i] <= miss) {
            miss += a[i];
            i++;
        } else {
            miss += miss;
            patches++;
        }
    }
    cout << patches << "\n";

    return 0;
}

